/* ------------------------------------------------------------------ hardware (simulated pins) */

function initHardware() {
  const used = new Map(SYSTEM_PINS);
  const alloc = (o, output) => {
    o.alloc = false; o.e = 0; o.owner = '';
    if (o.p < 0) return;
    if (!isPinOk(o.p, output)) { o.e = 1; return; }
    if (used.has(o.p)) { o.e = 2; o.owner = used.get(o.p); return; }
    used.set(o.p, 'Usermod');
    o.alloc = true;
  };
  for (const r of relays) { alloc(r, true); if (r.alloc && r.state) r.onSince = millis(); }
  for (const s of switches) { alloc(s, false); s.state = false; }
  for (const s of sensors) { alloc(s, false); s.motion = false; }
  settleUntil = millis() + K.HG_SETTLE_MS;
  settled = false;
}
function inputsSettling(now) { if (!settled && now >= settleUntil) settled = true; return !settled; }
function hardwareSignature() {
  return JSON.stringify([relays.map(r => [r.p, r.al]), switches.map(s => [s.p, s.t, s.inv]), sensors.map(s => s.p)]);
}

/* ------------------------------------------------------------------ relays, strips, moods, actions */

function setRelay(i, on, src) {
  if (i < 0 || i >= relays.length) return;
  restoreMask &= ~(1 << i);
  const r = relays[i];
  if (r.state === on) return;
  r.state = on;
  r.onSince = on ? millis() : 0;
  r.lastSrc = src;
  r.lastChange = uptimeSec();
  if (r.po === 2) { stateDirty = true; stateDirtyAt = millis(); }
}
function autoRelayOff(i, src) { if (i >= 0 && i < relays.length && !relays[i].keep) setRelay(i, false, src); }

function setStrips(mask, on) {
  const st = devState();
  const seg = [];
  for (let k = 0; k < K.HG_STRIPS; k++) {
    if (!(mask & (1 << k)) || !segAt(st, stripSeg[k])) continue;
    seg.push({ id: stripSeg[k], on });
  }
  if (on) devApply({ on: true, seg });   // "if (on && bri == 0) bri = briLast"
  else if (seg.length) devApply({ seg });
}

const isValidMood = id => id < BM.length || (id >= K.HG_MOOD_CUSTOM_BASE && id < K.HG_MOOD_CUSTOM_BASE + K.HG_CUSTOM_MOODS);

// applyMood(): effect and palette are resolved by name against the device's lists, then written to the strips in mask
function applyMood(id, mask) {
  if (!isValidMood(id)) return;
  let custom = null;
  if (id >= K.HG_MOOD_CUSTOM_BASE) {
    custom = moods[id - K.HG_MOOD_CUSTOM_BASE];
    if (!custom.used) return;
  } else {
    custom = moods.find(m => m.used && m.rep === id) || null;
  }
  let fx, pal, sx, ix, opacity, col;
  if (custom) {
    fx = findEffect(custom.fx); if (fx < 0) fx = custom.fxid;
    pal = findPalette(custom.pal); if (pal < 0) pal = custom.palid;
    sx = custom.sx; ix = custom.ix; opacity = custom.bri; col = custom.col;
  } else {
    const b = BM[id];
    fx = findEffect(b.fx); if (fx < 0) fx = 0;
    pal = findPalette(b.pal);
    if (pal < 0) pal = Math.max(0, extractModeDefaults(fx, 'pal'));
    sx = b.sx; ix = b.ix; opacity = b.bri; col = b.col;
  }
  const st = devState();
  const seg = [];
  for (let k = 0; k < K.HG_STRIPS; k++) {
    if (!(mask & (1 << k)) || !segAt(st, stripSeg[k])) continue;
    // seg.setMode(fx, true): the effect's default sliders load when the effect changes; the mood's values follow
    const o = { id: stripSeg[k], on: true, fx, fxdef: true, sx, ix, pal, col: col.map(colArr), bri: opacity };
    if (custom) Object.assign(o, { c1: custom.c1, c2: custom.c2, c3: custom.c3 & 0x1F, o1: custom.o1, o2: custom.o2, o3: custom.o3 });
    seg.push(o);
  }
  if (!seg.length) return;
  devApply({ on: true, seg });   // "if (bri == 0) bri = briLast"
}

function runActions(list) {
  for (const [t, target, strips] of list) {
    switch (t) {
      case ACT.RELAY_ON: setRelay(target, true, curSrc); break;
      case ACT.RELAY_OFF: autoRelayOff(target, curSrc); break;
      case ACT.RELAY_TOGGLE: if (target < relays.length) { if (relays[target].state) autoRelayOff(target, curSrc); else setRelay(target, true, curSrc); } break;
      case ACT.MOOD: applyMood(target, strips); break;
      case ACT.STRIP_ON: setStrips(strips, true); break;
      case ACT.STRIP_OFF: setStrips(strips, false); break;
      case ACT.ALL_RELAYS_OFF: for (let r = 0; r < relays.length; r++) autoRelayOff(r, curSrc); break;
      default: break;
    }
  }
}
// undoActions(): relays a sensor switched on go off, strips it lit go off
function undoActions(list) {
  for (const [t, target, strips] of list) {
    if (t === ACT.RELAY_ON) autoRelayOff(target, curSrc);
    else if (t === ACT.MOOD || t === ACT.STRIP_ON) setStrips(strips, false);
  }
}

// forwards the microphone preferences to audioreactive ("enabled" as the firmware sends it; device.js reads "on")
function applyAudioPrefs() {
  audioPrefsApplied = true;
  devApply({ AudioReactive: { enabled: micOn, on: micOn, inputLevel: micLevel } });
}

/* ------------------------------------------------------------------ command queue */

function queueCmd(type, a = 0, b = 0, src = SRC.APP) {
  if (queue.length >= K.HG_QUEUE_LEN) return false;
  queue.push({ type, a: u8(a), b: u8(b), src });
  return true;
}
function executeCmd(c) {
  switch (c.type) {
    case CMD.RELAY: if (c.a < relays.length) setRelay(c.a, c.b === RELAY_TOGGLE ? !relays[c.a].state : !!c.b, c.src); break;
    case CMD.MOOD: applyMood(c.a, c.b); break;
    case CMD.SCENE: if (c.a < scenes.length) { curSrc = SRC.SCENE; runActions(scenes[c.a].a); } break;
    case CMD.STRIP: setStrips(c.a, !!c.b); break;
    case CMD.ALL_OFF: for (let r = 0; r < relays.length; r++) autoRelayOff(r, SRC.ALLOFF); break;
    case CMD.MIC: if (micOn !== !!c.a) { micOn = !!c.a; markConfigDirty(); } applyAudioPrefs(); break;
    case CMD.LEVEL: if (micLevel !== c.a) { micLevel = c.a; markConfigDirty(); } applyAudioPrefs(); break;
    case CMD.AWAY: if (away.en !== !!c.a) { away.en = !!c.a; markConfigDirty(); } break;
    default: break;
  }
}
function markConfigDirty() { cfgDirty = true; cfgDirtyAt = millis(); }

