        fx: strl(orStr(o.fx, 'Solid'), K.HG_FXNAME_LEN), pal: strl(orStr(o.pal, ''), K.HG_FXNAME_LEN),
        fxid: u8(orInt(o.fxid, 0)), palid: u8(orInt(o.palid, 0)), sx: u8(orInt(o.sx, 128)), ix: u8(orInt(o.ix, 128)),
        c1: u8(orInt(o.c1, 128)), c2: u8(orInt(o.c2, 128)), c3: constrain(orInt(o.c3, 16), 0, 31),
