    cpp: FW.file, cpp_md5: FW.md5, page, page_md5: pageMd5, contract: 'v2.3 (GET /home/bm, fxsrc)',
    builtinMoods: BM.length, fxsrc: FXSRC, fxjs: FXSRC === 'none' ? null : fx, fxjs_md5: FXSRC === 'none' ? null : fxMd5, pin: !!PIN, randomPir: RANDOM_PIR, cfgFile: SAVE ? CFG_FILE : null,
