/* ------------------------------------------------------------------ start-up (setup()) */

// setup(): defaults, saved configuration, power-on states (relays that should be on follow one by one), pins.
// The key (NVS on the device) survives a simulated reboot.
function setup() {
  BOOT = Date.now() + advanced;   // millis() starts again at 0
  setDefaults();
  loadConfig();
  relays.forEach(r => { r.state = r.po === 1; });
  loadRelayStates();
  restoreMask = 0;
  relays.forEach((r, i) => { if (r.state) restoreMask |= 1 << i; r.state = false; });
  restoreNextAt = millis() + K.HG_RESTORE_STEP_MS;
  initHardware();
}
{
  const k = argVal('--hg-key') || process.env.HG_KEY;
  if (k && validKey(k)) apiKey = k;
  else { if (k) console.error('[home] ignoring the fixed key: it needs ' + K.HG_KEY_LEN + ' characters from "' + K.KEY_CHARS + '"'); generateKey(); }
}
setup();
console.log('[home] Home Gadgets ' + FW.release + ' (cpp md5 ' + FW.md5.slice(0, 8) + '), ' + BM.length + ' built-in moods, page ' + pageFile());
console.log('[home] API key for this run: ' + apiKey + (PIN ? '   (settings PIN ' + PIN + ')' : ''));
// attach to device.js by itself if server.js loads it (the contract passes dev to handle()/upgrade() anyway)
setImmediate(() => {
  try { const id = require.resolve('./device.js'); if (require.cache[id]) attach(require.cache[id].exports); } catch (_) { /* no device.js */ }
});

module.exports = {
  handle, upgrade, homeInfo, addToJsonState, addToJsonInfo, attach, sim, checkSettingsPIN,
  apiKey: () => apiKey,
  // test hooks
  _test: {
    setPin(p) { PIN = String(p || '').slice(0, 4); lastEditTime = 0; correctPIN = false; },
    setFxsrc(v) { FXSRC = v; },
    stop() { if (loopTimer) clearInterval(loopTimer); loopTimer = null; if (pirTimer) clearTimeout(pirTimer); pirTimer = null; },
    start() { if (!loopTimer) { loopTimer = setInterval(loop, LOOP_MS); loopTimer.unref(); } },
    builtin: BM, K, release: FW.release, wsClients: () => ws.clients.filter(c => c && c.isOpen).length,
    settle() { settled = true; },
    // virtual clock (probe_rc3.js: --time and /__time): set the local time, or advance it while loop() keeps running
    setTime(local) { const t = new Date(String(local).replace(' ', 'T')).getTime(); if (Number.isFinite(t)) clockOffset += t - wallNow(); },
    advance(ms, stepMs = 100) { for (let done = 0; done < ms; done += stepMs) { const d = Math.min(stepMs, ms - done); clockOffset += d; advanced += d; loop(); } },
    localTime() { return new Date(localClock() * 1000).toISOString().replace('T', ' ').slice(0, 19); },
    reboot() { ws.clients.forEach(c => c && c.close()); setup(); },
    files() { const rd = f => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch (_) { return undefined; } }; return SAVE ? { [CFG_FILE]: rd(CFG_FILE), [STATE_FILE]: rd(STATE_FILE) } : {}; },
  },
};
